.lh{position:relative;z-index:2;margin-top:auto;margin-bottom:auto;padding:36px 0}
.lh h1{font-family:'Space Grotesk',sans-serif;font-size:54px;font-weight:800;color:#fff;line-height:1.05;letter-spacing:-3px;margin-bottom:22px}
