.lferr{background:#fff1f2;border:1px solid #fecdd3;color:var(--red);padding:13px 16px;border-radius:11px;font-size:14px;margin-bottom:18px}
.lfdemo{margin-top:30px;padding:18px 20px;background:linear-gradient(135deg,#fefdf8,#fffef5);border-radius:13px;border:1px solid rgba(212,168,67,0.38);box-shadow:0 2px 14px rgba(212,168,67,0.1)}
