  id: "M20 4H4c-1.11 0-2 .89-2 2v12c0 1.11.89 2 2 2h16c1.11 0 2-.89 2-2V6c0-1.11-.89-2-2-2zm-7 2h2v5h-2V6zm0 7h2v2h-2v-2zM8 6h5v2H8V6zm0 4h5v2H8v-2zm0 4h5v2H8v-2zm-1 2H5v-2h2v2zm0-4H5v-2h2v2zm0-4H5V6h2v2z",
