// HELPERS
const useToasts = () => {
  const [ts, setTs] = useState([]);
  const add = useCallback((msg, type = "ok") => {
    const id = Date.now() + Math.random();
    setTs(p => [...p, { id, msg, type }]);
    setTimeout(() => setTs(p => p.filter(t => t.id !== id)), 3800);
  }, []);
  return { ts, add };
};
const Toasts = ({ ts }) => (
  <div className="tstack">{ts.map(t => <div key={t.id} className={`toast ${t.type === "ok" ? "tok" : "ter"}`}><Ic n={t.type === "ok" ? "ok" : "ban"} s={18} c={t.type === "ok" ? "#1db87a" : "#f43f5e"} />{t.msg}</div>)}</div>
);
