// FACE SCAN
const FaceScan = ({ name, onDone, onClose }) => {
  const vid = useRef(null);
  const [ph, setPh] = useState("init");
  const [lbl, setLbl] = useState("Starting camera...");
  const [conf, setConf] = useState(0);
  useEffect(() => {
    navigator.mediaDevices.getUserMedia({ video: { width: 640, height: 480, facingMode: "user" } })
      .then(s => { if (vid.current) vid.current.srcObject = s; setPh("ready"); setLbl("Position your face in the frame"); })
      .catch(() => setPh("err"));
    return () => { if (vid.current?.srcObject) vid.current.srcObject.getTracks().forEach(t => t.stop()); };
  }, []);
  const scan = () => {
    setPh("scan"); setLbl("Detecting facial landmarks...");
    [[600,"Analyzing facial geometry..."],[1400,"Extracting biometric features..."],[2100,"Matching identity database..."],[2700,"Computing confidence score..."]].forEach(([ms,txt]) => setTimeout(() => { setLbl(txt); setConf(Math.min(98,Math.round((ms/2700)*98))); }, ms));
    setTimeout(() => { setPh("done"); setConf(98); }, 3400);
  };
  const finish = () => { if (vid.current?.srcObject) vid.current.srcObject.getTracks().forEach(t => t.stop()); onDone(); };
  const close = () => { if (vid.current?.srcObject) vid.current.srcObject.getTracks().forEach(t => t.stop()); onClose(); };
  return (
    <Modal title="Face Recognition" sub={`Biometric verification — ${name}`} onClose={close}
      footer={ph==="ready"?<><button className="btn btngh" onClick={close}>Cancel</button><button className="btn btnt" onClick={scan}><Ic n="cam" s={16} c="#fff"/>Begin Scan</button></>:ph==="scan"?<button className="btn btngh" disabled>Analyzing...</button>:ph==="done"?<><button className="btn btngh" onClick={close}>Close</button><button className="btn btng" onClick={finish}><Ic n="ok" s={16} c="#fff"/>Confirm Identity</button></>:<button className="btn btngh" onClick={close}>Close</button>}>
      <div className="cam">
        <video ref={vid} autoPlay muted playsInline style={{width:"100%",height:"100%",objectFit:"cover"}}/>
        {(ph==="ready"||ph==="scan")&&<><div className="camsh"/><div className="cambr"/><div className="cambr2"/><div className="campulse"/>{ph==="scan"&&<div className="camscan"/>}<div className="camlbl">{lbl}</div></>}
        {ph==="done"&&<div className="camok"><div className="camokic"><Ic n="ok" s={34} c="#0f8a5f"/></div><div className="camokt">Identity Verified</div><div className="camoks">{name} · Confidence: 98%</div></div>}
        {ph==="err"&&<div className="camerr"><Ic n="warn" s={30} c="#f43f5e"/><span>Camera access denied.<br/><span style={{fontSize:13,opacity:0.7}}>Allow camera permission in browser settings.</span></span></div>}
        {ph==="init"&&<div className="camerr" style={{background:"rgba(0,0,0,0.7)"}}><span style={{color:"#fff",fontSize:15}}>Starting camera...</span></div>}
      </div>
      {ph==="scan"&&conf>0&&(
        <div style={{marginTop:18,padding:"16px 18px",background:"var(--bg)",borderRadius:12,border:"1px solid var(--border)"}}>
          <div style={{display:"flex",justifyContent:"space-between",fontSize:13,fontWeight:700,marginBottom:7}}><span style={{color:"var(--muted)"}}>Confidence Score</span><span style={{color:"var(--v)"}}>{conf}%</span></div>
          <div className="confbar"><div className="conffill" style={{width:`${conf}%`,background:"linear-gradient(90deg,var(--v),var(--teal2))"}}/></div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:10,marginTop:14}}>
            {[["Liveness Check",conf>30],["Face Detected",conf>55],["Identity Match",conf>85]].map(([l,ok])=>(
              <div key={l} style={{textAlign:"center",padding:"10px 6px",background:ok?"rgba(29,184,122,0.1)":"var(--white)",border:`1px solid ${ok?"rgba(29,184,122,0.3)":"var(--border)"}`,borderRadius:10}}>
                <div style={{fontSize:18,marginBottom:3}}>{ok?"✓":"..."}</div>
                <div style={{fontSize:11,color:ok?"var(--green)":"var(--faint)",fontWeight:700}}>{l}</div>
              </div>
            ))}
          </div>
        </div>
      )}
    </Modal>
  );
};

