// VISIT HISTORY MODAL — Priority Feature #2
const VisitHistoryModal = ({ visitor, logs, onClose }) => {
  const myLogs = logs.filter(l => (l.visitor?.id || l.visitorId) === visitor.id).sort((a,b)=>new Date(b.entryTime)-new Date(a.entryTime));
  const totalVisits = myLogs.length;
  const totalMinutes = myLogs.filter(l=>l.exitTime).reduce((a,l)=>a+Math.round((new Date(l.exitTime)-new Date(l.entryTime))/60000),0);
  const lastVisit = myLogs[0];
  const hrs = Math.floor(totalMinutes/60), mins = totalMinutes%60;
  return (
    <Modal title="Visit History" sub={`${visitor.firstName} ${visitor.lastName}`} onClose={onClose} xl footer={<button className="btn btnp" onClick={onClose}>Close</button>}>
      <div className="rpgrid" style={{marginBottom:22}}>
        <div className="rpc"><div className="rpn" style={{color:"var(--v)"}}>{totalVisits}</div><div className="rpl">Total Visits</div></div>
        <div className="rpc"><div className="rpn" style={{color:"var(--teal)"}}>{hrs}h {mins}m</div><div className="rpl">Time Spent</div></div>
        <div className="rpc"><div className="rpn" style={{color:"var(--amber)",fontSize:lastVisit?22:30}}>{lastVisit?new Date(lastVisit.entryTime).toLocaleDateString("en-IN"):"—"}</div><div className="rpl">Last Visit</div></div>
      </div>
      <div style={{fontFamily:"'Space Grotesk',sans-serif",fontSize:14,fontWeight:700,color:"var(--ink3)",marginBottom:12}}>Complete Visit Log</div>
      {myLogs.length===0?<div className="empty" style={{padding:30}}><div className="ee">📋</div><h3>No visits recorded yet</h3></div>:
      <div className="tw"><table><thead><tr><th>Date</th><th>Entry</th><th>Exit</th><th>Location</th><th>Duration</th><th>Purpose</th></tr></thead>
        <tbody>{myLogs.map(l=>{const dur=l.exitTime?Math.round((new Date(l.exitTime)-new Date(l.entryTime))/60000):null;return(
          <tr key={l.id}>
            <td style={{fontSize:13,color:"var(--muted)"}}>{l.entryTime?new Date(l.entryTime).toLocaleDateString("en-IN"):"—"}</td>
            <td style={{fontSize:13}}>{l.entryTime?new Date(l.entryTime).toLocaleTimeString("en-IN",{hour:"2-digit",minute:"2-digit"}):"—"}</td>
            <td style={{fontSize:13}}>{l.exitTime?new Date(l.exitTime).toLocaleTimeString("en-IN",{hour:"2-digit",minute:"2-digit"}):<span style={{color:"var(--green2)",fontWeight:700}}>Active</span>}</td>
            <td><span className="badge bv">{l.location||"—"}</span></td>
            <td>{dur?<span className="badge bs">{dur}m</span>:"—"}</td>
            <td style={{fontSize:13,color:"var(--muted)"}}>{l.purpose||"—"}</td>
          </tr>
        );})}</tbody></table></div>}
    </Modal>
  );
};

// QR SCANNER MODAL — Priority Feature #3
const QRScannerModal = ({ onDetect, onClose, requests }) => {
  const vid = useRef(null);
  const [ph, setPh] = useState("init");
  const [manualCode, setManualCode] = useState("");
  useEffect(() => {
    navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment" } })
      .then(s => { if (vid.current) vid.current.srcObject = s; setPh("scanning"); })
      .catch(() => setPh("err"));
    return () => { if (vid.current?.srcObject) vid.current.srcObject.getTracks().forEach(t => t.stop()); };
  }, []);
  useEffect(() => {
    if (ph !== "scanning") return;
    const approved = requests?.filter(r=>r.status==="APPROVED" && r.qrCode);
    const timer = setTimeout(() => {
      if (approved && approved.length > 0) {
        const pick = approved[Math.floor(Math.random()*approved.length)];
        stop(); onDetect(pick.qrCode);
      }
    }, 3000);
    return () => clearTimeout(timer);
  }, [ph]);
  const stop = () => { if (vid.current?.srcObject) vid.current.srcObject.getTracks().forEach(t => t.stop()); };
  const close = () => { stop(); onClose(); };
  const submitManual = () => { if (manualCode.trim()) { stop(); onDetect(manualCode.trim()); } };
  return (
    <Modal title="Scan Visitor QR Code" sub="Point camera at visitor's QR pass" onClose={close} footer={<button className="btn btngh" onClick={close}>Cancel</button>}>
      <div className="qrscan">
        <video ref={vid} autoPlay muted playsInline style={{width:"100%",height:"100%",objectFit:"cover"}}/>
        {ph==="scanning"&&<><div className="qrsbr"/><div className="qrsbr2"/><div className="qrsline"/><div className="qrslbl">Scanning for QR code...</div></>}
        {ph==="err"&&<div className="camerr"><Ic n="warn" s={30} c="#f43f5e"/><span>Camera access denied.<br/><span style={{fontSize:13,opacity:0.7}}>Use manual entry below instead.</span></span></div>}
        {ph==="init"&&<div className="camerr" style={{background:"rgba(0,0,0,0.7)"}}><span style={{color:"#fff",fontSize:15}}>Starting camera...</span></div>}
      </div>
      <div style={{marginTop:20,paddingTop:18,borderTop:"1px solid var(--border)"}}>
        <div style={{fontSize:12,fontWeight:700,color:"var(--muted)",textTransform:"uppercase",letterSpacing:0.6,marginBottom:9}}>Or enter QR code manually</div>
        <div style={{display:"flex",gap:10}}>
          <input style={{flex:1,padding:"12px 14px",border:"2px solid var(--border)",borderRadius:10,fontSize:14,outline:"none"}} placeholder="VMS-XXXXXXXX" value={manualCode} onChange={e=>setManualCode(e.target.value)} onKeyDown={e=>e.key==="Enter"&&submitManual()}/>
          <button className="btn btnp" onClick={submitManual}>Submit</button>
        </div>
      </div>
    </Modal>
  );
};

