// VISITORS — with Returning Visitor Detection (Priority #1) + Visit History (Priority #2)
const VisitorsPage = ({ token, toast }) => {
  const [list, setList] = useState([]);
  const [logs, setLogs] = useState([]);
  const [q, setQ] = useState("");
  const [show, setShow] = useState(false);
  const [histVisitor, setHistVisitor] = useState(null);
  const [f, setF] = useState({ firstName:"",lastName:"",phone:"",email:"",idProofType:"AADHAR",idProofNumber:"",companyName:"" });
  const [match, setMatch] = useState(null);
  const load = useCallback(()=>apiFetch("/visitors","GET",null,token).then(setList).catch(()=>{}),[token]);
  const loadLogs = useCallback(()=>apiFetch("/entry-logs","GET",null,token).then(setLogs).catch(()=>{}),[token]);
  useEffect(()=>{load();loadLogs();},[load,loadLogs]);

  // Returning visitor detection — checks phone or email against existing list
  const checkReturning = (phone, email) => {
    if (!phone && !email) { setMatch(null); return; }
    const found = list.find(v => (phone && v.phone === phone) || (email && v.email.toLowerCase() === email.toLowerCase()));
    setMatch(found || null);
  };
  const onPhoneChange = val => { setF({...f, phone: val}); checkReturning(val, f.email); };
  const onEmailChange = val => { setF({...f, email: val}); checkReturning(f.phone, val); };
  const useExisting = () => {
    setF({ firstName: match.firstName, lastName: match.lastName, phone: match.phone, email: match.email, idProofType: match.idProofType, idProofNumber: match.idProofNumber, companyName: match.companyName||"" });
    toast(`Loaded existing record for ${match.firstName} ${match.lastName}`,"ok");
  };
  const visitCount = vId => logs.filter(l => (l.visitor?.id||l.visitorId) === vId).length;

  const save = async()=>{
    try{
      if (match) { toast(`${match.firstName} is already registered — no need to re-register!`,"ok"); setShow(false); return; }
      await apiFetch("/visitors","POST",f,token);toast("Visitor registered!","ok");setShow(false);setF({firstName:"",lastName:"",phone:"",email:"",idProofType:"AADHAR",idProofNumber:"",companyName:""});setMatch(null);load();
    }catch{toast("Failed","err");}
  };
  const closeModal = () => { setShow(false); setMatch(null); setF({firstName:"",lastName:"",phone:"",email:"",idProofType:"AADHAR",idProofNumber:"",companyName:""}); };
  const fil = list.filter(v=>`${v.firstName} ${v.lastName} ${v.email} ${v.phone}`.toLowerCase().includes(q.toLowerCase()));

  return (
    <div>
      <div className="ph"><div><h2>Visitors</h2><p className="phs">{list.length} registered visitors in the system</p></div>
        <div className="phr">
          <div className="sw2"><span className="sw2ic"><Ic n="search" s={17}/></span><input style={{width:250,padding:"10px 14px 10px 42px",border:"1.5px solid var(--border)",borderRadius:11,fontSize:15,outline:"none",background:"#fff"}} placeholder="Search visitors..." value={q} onChange={e=>setQ(e.target.value)}/></div>
          <button className="btn btnp" onClick={()=>setShow(true)}><Ic n="plus" s={18} c="#fff"/>Register Visitor</button>
        </div>
      </div>
      <div className="panel"><div className="tw">
        {fil.length===0?<div className="empty"><div className="ee">👤</div><h3>No visitors found</h3><p>Register a new visitor to get started</p></div>:(
          <table><thead><tr><th>Visitor</th><th>Phone</th><th>Company</th><th>ID Type</th><th>Visits</th><th>History</th></tr></thead>
          <tbody>{fil.map(v=>{const vc=visitCount(v.id);return(
            <tr key={v.id}>
              <td><div className="pc"><div className="av avi">{v.firstName?.[0]}{v.lastName?.[0]}</div><div><div className="pn">{v.firstName} {v.lastName}</div><div className="pe">{v.email}</div></div></div></td>
              <td>{v.phone}</td><td style={{color:"var(--muted)",fontSize:14}}>{v.companyName||"—"}</td>
              <td><span className="badge bb">{v.idProofType}</span></td>
              <td>{vc>0?<span className="badge bgold">⭐ {vc}x</span>:<span className="badge bs">New</span>}</td>
              <td><button className="btn btnou btnxs" onClick={()=>setHistVisitor(v)}><Ic n="history" s={13}/>View</button></td>
            </tr>
          );})}</tbody></table>
        )}
      </div></div>
      {show&&<Modal title="Register New Visitor" sub="Enter phone or email to auto-detect returning visitors" onClose={closeModal} footer={<><button className="btn btngh" onClick={closeModal}>Cancel</button>{match?<button className="btn btngold" onClick={useExisting}><Ic n="star" s={16} c="#fff"/>Use Existing Record</button>:<button className="btn btnp" onClick={save}>Register Visitor</button>}</>}>
        {match&&(
          <div className="rvb">
            <div className="rvbic"><Ic n="star" s={22} c="#fff"/></div>
            <div style={{flex:1}}>
              <div className="rvbtt">Welcome Back, {match.firstName}!</div>
              <div className="rvbsb">This visitor is already registered ({visitCount(match.id)} previous visit{visitCount(match.id)!==1?"s":""}). Click "Use Existing Record" to skip registration.</div>
            </div>
          </div>
        )}
        <div className="fg"><div className="field"><label>First Name *</label><input value={f.firstName} onChange={e=>setF({...f,firstName:e.target.value})} placeholder="John"/></div><div className="field"><label>Last Name *</label><input value={f.lastName} onChange={e=>setF({...f,lastName:e.target.value})} placeholder="Doe"/></div></div>
        <div className="fg"><div className="field"><label>Phone *</label><input value={f.phone} onChange={e=>onPhoneChange(e.target.value)} placeholder="9876543210"/></div><div className="field"><label>Email *</label><input type="email" value={f.email} onChange={e=>onEmailChange(e.target.value)} placeholder="john@company.com"/></div></div>
        <div className="fg"><div className="field"><label>ID Proof Type</label><select value={f.idProofType} onChange={e=>setF({...f,idProofType:e.target.value})}><option>AADHAR</option><option>PAN</option><option>PASSPORT</option><option>DRIVING_LICENSE</option><option>VOTER_ID</option></select></div><div className="field"><label>ID Number</label><input value={f.idProofNumber} onChange={e=>setF({...f,idProofNumber:e.target.value})} placeholder="XXXX-XXXX-XXXX"/></div></div>
        <div className="fg full"><div className="field"><label>Company / Organization</label><input value={f.companyName} onChange={e=>setF({...f,companyName:e.target.value})} placeholder="Company Name"/></div></div>
      </Modal>}
      {histVisitor&&<VisitHistoryModal visitor={histVisitor} logs={logs} onClose={()=>setHistVisitor(null)}/>}
    </div>
  );
};

