          <div style={{padding:"22px 24px"}}>
            {[{l:"Approved",n:approved,c:"var(--green2)"},{l:"Pending",n:pending2,c:"var(--amber2)"},{l:"Rejected",n:rejected,c:"var(--rose2)"}].map(row=>(
              <div key={row.l} style={{marginBottom:18}}>
                <div style={{display:"flex",justifyContent:"space-between",fontSize:15,fontWeight:700,marginBottom:7}}><span style={{color:"var(--ink3)"}}>{row.l}</span><span style={{color:row.c}}>{row.n}</span></div>
                <div className="sbar"><div className="sfill" style={{width:requests.length?`${Math.round((row.n/requests.length)*100)}%`:"0%",background:row.c}}/></div>
              </div>
            ))}
          </div>
        </div>
        <div className="panel">
          <div className="ph2"><div><div className="pt">Recent Activity</div><div className="ps">Latest entry logs</div></div></div>
          <div style={{padding:"0 24px 18px"}}>
            {[...logs].sort((a,b)=>new Date(b.entryTime)-new Date(a.entryTime)).slice(0,6).map(l=>(
              <div className="tlitem" key={l.id}>
                <div className="tldot" style={{background:l.exitTime?"rgba(29,78,216,0.1)":"rgba(15,138,95,0.1)"}}><Ic n="door" s={20} c={l.exitTime?"var(--v)":"var(--green)"}/></div>
                <div style={{flex:1}}>
                  <div className="tltt">{l.visitor?.firstName} {l.visitor?.lastName}</div>
                  <div className="tlsb">{l.exitTime?"Checked out":"Checked in"} · {l.location||l.purpose||"Visit"}</div>
