        <div style={{padding:"22px 24px"}}>
          {floorEntries.length===0?<div className="empty" style={{padding:30}}><div className="ee">🏢</div><h3>No location data recorded yet</h3></div>:
            floorEntries.map(([floor,count],i)=>(
              <div key={floor} style={{marginBottom:16}}>
                <div style={{display:"flex",justifyContent:"space-between",fontSize:14,fontWeight:600,marginBottom:6}}><span style={{color:"var(--ink3)"}}>{floor}</span><span style={{color:floorColors[i%floorColors.length]}}>{count} visits</span></div>
