// SECURITY GUARD CONSOLE — Priority #3 (QR Scanner) + #4 (Dedicated Dashboard)
const GuardConsole = ({ token, toast }) => {
  const [requests, setRequests] = useState([]);
  const [visitors, setVisitors] = useState([]);
  const [logs, setLogs] = useState([]);
  const [showScanner, setShowScanner] = useState(false);
  const [matched, setMatched] = useState(null); // matched request after QR detect
  const [showFace, setShowFace] = useState(false);
  const [faceOk, setFaceOk] = useState(false);
  const [location, setLocation] = useState(FLOORS[0]);
  const [showGP, setShowGP] = useState(null);

  const load = useCallback(async()=>{try{const[r,v,l]=await Promise.all([apiFetch("/visit-requests","GET",null,token),apiFetch("/visitors","GET",null,token),apiFetch("/entry-logs","GET",null,token)]);setRequests(r);setVisitors(v);setLogs(l);}catch{}},[token]);
  useEffect(()=>{load();},[load]);

  const insideList = logs.filter(l=>!l.exitTime);
  const today = new Date().toISOString().slice(0,10);
  const expectedToday = requests.filter(r=>r.status==="APPROVED" && r.visitDate===today);

  const onDetect = (qrCode) => {
    setShowScanner(false);
    const req = requests.find(r => r.qrCode === qrCode);
    if (!req) { toast("QR code not recognized — no matching approved request","err"); return; }
    if (req.status !== "APPROVED") { toast(`This request is ${req.status.toLowerCase()} — entry denied`,"err"); return; }
    setMatched(req);
    setFaceOk(false);
    toast(`Visitor identified: ${req.visitor?.firstName} ${req.visitor?.lastName}`,"ok");
  };

  const confirmCheckin = async () => {
    try {
      const r = await apiFetch("/entry-logs/checkin","POST",{ visitorId: matched.visitor.id, purpose: matched.purpose, location },token);
      toast("Checked in successfully! Gate pass ready.","ok");
      setShowGP({...r, visitor: matched.visitor, location});
      setMatched(null); setFaceOk(false);
      load();
    } catch { toast("Check-in failed","err"); }
  };

  const checkout = async id=>{try{await apiFetch(`/entry-logs/checkout/${id}`,"PUT",null,token);toast("Visitor checked out!","ok");load();}catch{toast("Failed","err");}};

  return (
    <div className="gconsole">
      <div className="gctop">
        <div>
          <div className="gctitle">🛡️ Security Guard Console</div>
          <div className="gcsub">Scan visitor QR codes for instant identity verification and check-in</div>
        </div>
        <button className="btn btngold" onClick={()=>setShowScanner(true)} style={{padding:"14px 26px",fontSize:15}}><Ic n="scan" s={20} c="#fff"/>Scan QR Code</button>
      </div>

      {matched && (
        <div className="gcvisitor" style={{marginBottom:22}}>
          <div style={{display:"flex",gap:16,alignItems:"flex-start"}}>
            <div className="av avgold">{matched.visitor?.firstName?.[0]}{matched.visitor?.lastName?.[0]}</div>
            <div style={{flex:1}}>
              <div style={{fontFamily:"'Space Grotesk',sans-serif",fontSize:18,fontWeight:800,color:"#fff"}}>{matched.visitor?.firstName} {matched.visitor?.lastName}</div>
              <div style={{fontSize:13,color:"rgba(255,255,255,0.5)",marginTop:2}}>{matched.visitor?.phone} · Meeting {matched.employee?.firstName} {matched.employee?.lastName}</div>
              <div style={{marginTop:8}}><span className="badge bg">✓ APPROVED</span></div>
            </div>
          </div>
          <div style={{marginTop:18}}>
            <div style={{fontSize:12,fontWeight:700,color:"rgba(255,255,255,0.5)",textTransform:"uppercase",letterSpacing:0.6,marginBottom:9}}>Destination Floor</div>
            <select value={location} onChange={e=>setLocation(e.target.value)} style={{width:"100%",padding:"11px 14px",borderRadius:10,border:"1px solid rgba(255,255,255,0.15)",background:"rgba(255,255,255,0.07)",color:"#fff",fontSize:14,outline:"none"}}>
              {FLOORS.map(fl=><option key={fl} value={fl} style={{color:"#000"}}>{fl}</option>)}
            </select>
          </div>
          {faceOk && <div className="ib ibg" style={{marginTop:14,marginBottom:0}}><Ic n="ok" s={16} c="var(--green2)"/>Face Verified — 98% confidence</div>}
          <div style={{display:"flex",gap:10,marginTop:16}}>
            <button className="btn btngh" style={{flex:1}} onClick={()=>setMatched(null)}>Cancel</button>
            {!faceOk && <button className="btn btnt" style={{flex:1}} onClick={()=>setShowFace(true)}><Ic n="face" s={16} c="#fff"/>Verify Face</button>}
            <button className="btn btng" style={{flex:1}} onClick={confirmCheckin}><Ic n="ok" s={16} c="#fff"/>Confirm Check-In</button>
          </div>
        </div>
      )}

      <div className="gcgrid">
        <div className="gcpanel">
          <h4><Ic n="door" s={16} c="rgba(255,255,255,0.6)"/>Currently Inside ({insideList.length})</h4>
          <div className="gclist">
            {insideList.length===0?<div className="gcempty">No visitors inside right now</div>:
              insideList.map(l=>(
                <div className="gcitem" key={l.id}>
                  <div className="av avg" style={{width:34,height:34,fontSize:12}}>{l.visitor?.firstName?.[0]}{l.visitor?.lastName?.[0]}</div>
                  <div style={{flex:1}}><div className="gcname">{l.visitor?.firstName} {l.visitor?.lastName}</div><div className="gcmeta">{l.location||"—"} · since {l.entryTime?new Date(l.entryTime).toLocaleTimeString("en-IN",{hour:"2-digit",minute:"2-digit"}):"—"}</div></div>
                  <button className="btn btngh btnxs" onClick={()=>checkout(l.id)}>Check Out</button>
                </div>
              ))
            }
          </div>
        </div>
        <div className="gcpanel">
          <h4><Ic n="clock2" s={16} c="rgba(255,255,255,0.6)"/>Expected Today ({expectedToday.length})</h4>
          <div className="gclist">
            {expectedToday.length===0?<div className="gcempty">No approved visits scheduled today</div>:
              expectedToday.map(r=>(
                <div className="gcitem" key={r.id}>
                  <div className="av avi" style={{width:34,height:34,fontSize:12}}>{r.visitor?.firstName?.[0]}{r.visitor?.lastName?.[0]}</div>
                  <div style={{flex:1}}><div className="gcname">{r.visitor?.firstName} {r.visitor?.lastName}</div><div className="gcmeta">Meeting {r.employee?.firstName} {r.employee?.lastName}</div></div>
                  <span className="badge bg">Approved</span>
                </div>
              ))
            }
          </div>
        </div>
      </div>

      {showScanner && <QRScannerModal requests={requests} onDetect={onDetect} onClose={()=>setShowScanner(false)}/>}
      {showFace && <FaceScan name={`${matched?.visitor?.firstName} ${matched?.visitor?.lastName}`} onDone={()=>{setShowFace(false);setFaceOk(true);toast("Face verified!","ok");}} onClose={()=>setShowFace(false)}/>}
      {showGP && <GatePassModal entry={showGP} visitors={visitors} onClose={()=>setShowGP(null)}/>}
    </div>
  );
};

// LOGIN
const LoginPage = ({ onLogin }) => {
  const [f, setF] = useState({ username:"",password:"" });
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);
  const go = async()=>{
    if(!f.username||!f.password){setErr("Please enter your username and password");return;}
    setBusy(true);setErr("");
    try{const r=await apiFetch("/auth/login","POST",f);if(r.success)onLogin(r);else setErr(r.message||"Invalid credentials");}
    catch{setErr("Cannot reach server. Ensure backend is running on port 8085.");}
    setBusy(false);
  };
  const feats=["QR Code-Based Entry System","Real-Time Visitor Tracking","Face Recognition + Liveness Check","Returning Visitor Auto-Detection","Building & Floor Tracking","Security Guard QR Scanner","Printable Gate Passes","Blacklist Management"];
  return (
    <div className="lr">
      <div className="lp">
        <div className="lg lg1"/><div className="lg lg2"/><div className="lg lg3"/>
        <div className="ll"><div className="llm">🏢</div><div><div className="lln">SAAD Enterprise</div><div className="llt">Visitor Management System v2.0</div></div></div>
        <div className="lh">
          <h1>Secure <span className="gd">Smart</span><br/>Visitor Control</h1>
          <p>Enterprise-grade visitor management with QR-based entry, real-time tracking, biometric face verification and automated email delivery.</p>
          <div className="lpills">{feats.map((ft,i)=><div className="lpill" key={i}><Ic n="ok" s={14} c="rgba(212,168,67,0.72)"/>{ft}</div>)}</div>
        </div>
        <div className="lfoot">© 2026 SAAD Enterprise — All Rights Reserved</div>
      </div>
      <div className="lrp">
        <div className="lf">
          <div className="lfey"><span>SAAD Enterprise Portal</span><span className="lfeyl"/></div>
          <h2>Welcome back</h2>
          <p className="sub">Sign in to the visitor management system</p>
          {err&&<div className="lferr">⚠️ {err}</div>}
          <label className="lflb">Username</label>
          <input className="lfin" value={f.username} onChange={e=>setF({...f,username:e.target.value})} placeholder="Enter your username" onKeyDown={e=>e.key==="Enter"&&go()} autoFocus/>
          <label className="lflb">Password</label>
          <input className="lfin" type="password" value={f.password} onChange={e=>setF({...f,password:e.target.value})} placeholder="Enter your password" onKeyDown={e=>e.key==="Enter"&&go()}/>
          <button className="lfbtn" onClick={go} disabled={busy}>{busy?"Signing in...":"Sign In →"}</button>
          <div className="lfdemo">
            <div className="lfdt">⚡ Demo Credentials</div>
            {[["Admin","admin / admin123"],["Security","security / security123"]].map(([r,c])=><div className="lfdr" key={r}><span className="lfdrk">{r}</span><span className="lfdrv">{c}</span></div>)}
          </div>
        </div>
      </div>
    </div>
  );
};

// APP ROOT
export default function App() {
  const [user, setUser] = useState(null);
  const [page, setPage] = useState("dashboard");
  const { ts, add: toast } = useToasts();

  const isSecurity = user?.role === "SECURITY";

  const NAV = [
    { sec:"Overview", items:[{id:"dashboard",l:"Dashboard",ic:"home"}] },
    ...(isSecurity ? [{ sec:"Security", items:[{id:"guard",l:"Guard Console",ic:"scan"}] }] : []),
    { sec:"Visitor Management", items:[{id:"visitors",l:"Visitors",ic:"people"},{id:"requests",l:"Visit Requests",ic:"qr"},{id:"entrylogs",l:"Entry Logs",ic:"door"}] },
    { sec:"Organization", items:[{id:"employees",l:"Employees",ic:"person"},{id:"departments",l:"Departments",ic:"bldg"}] },
    { sec:"Administration", items:[{id:"reports",l:"Reports",ic:"chart"},{id:"blacklist",l:"Blacklist",ic:"ban"},{id:"admins",l:"System Users",ic:"shield"}] },
  ];
  const META = {
    dashboard:{t:"Dashboard",s:"Live overview of visitor activity — SAAD Enterprise"},
    guard:{t:"Guard Console",s:"Scan QR codes for instant visitor verification"},
    visitors:{t:"Visitors",s:"Registered visitor records — auto-detects returning visitors"},
    requests:{t:"Visit Requests",s:"QR passes, approvals and face verification"},
    entrylogs:{t:"Entry Logs",s:"Real-time check-in · check-out · floor tracking · gate passes"},
    employees:{t:"Employees",s:"Staff who can host visitors"},
    departments:{t:"Departments",s:"Organizational structure"},
    reports:{t:"Reports & Analytics",s:"System-wide statistics, activity and floor traffic"},
    blacklist:{t:"Blacklist",s:"Blocked visitors — auto-denied on entry"},
    admins:{t:"System Users",s:"Multiple admin accounts and access control"},
  };

  if(!user) return(<><style>{CSS}</style><LoginPage onLogin={u=>{setUser(u);setPage(u.role==="SECURITY"?"guard":"dashboard");}}/></>);

  return (
    <>
      <style>{CSS}</style>
      <div className="app">
        <div className="sb">
          <div className="sbtop"><div className="sbbrand"><div className="sbmk">🏢</div><div><div className="sbnm">SAAD Enterprise</div><div className="sbtg">Visitor Management</div></div></div></div>
          <div className="sbnav">
            {NAV.map(sec=>(
              <React.Fragment key={sec.sec}>
                <div className="sbsc">{sec.sec}</div>
                {sec.items.map(item=><div key={item.id} className={`sbit ${page===item.id?"on":""}`} onClick={()=>setPage(item.id)}><Ic n={item.ic} s={19} c={page===item.id?"var(--v3)":"currentColor"}/>{item.l}</div>)}
              </React.Fragment>
            ))}
          </div>
          <div className="sbft">
            <div className="sbus"><div className="sbav">{user.username?.[0]?.toUpperCase()}</div><div><div className="sbun">{user.username}</div><div className="sbur">{user.role}</div></div></div>
            <button className="sblo" onClick={()=>setUser(null)}><Ic n="out" s={16}/>Sign Out</button>
          </div>
        </div>
        <div className="main">
          <div className="topbar">
            <div><div className="tbt">{META[page]?.t}</div><div className="tbs">{META[page]?.s}</div></div>
            <div className="tbst"><span className="tbd"/>System Online — SAAD Enterprise</div>
          </div>
          <div className="ct">
            {page==="dashboard"   && <Dashboard token={user.token}/>}
            {page==="guard"       && <GuardConsole token={user.token} toast={toast}/>}
            {page==="visitors"    && <VisitorsPage token={user.token} toast={toast}/>}
            {page==="requests"    && <RequestsPage token={user.token} toast={toast}/>}
            {page==="entrylogs"   && <EntryLogsPage token={user.token} toast={toast}/>}
            {page==="employees"   && <EmployeesPage token={user.token} toast={toast}/>}
            {page==="departments" && <DepartmentsPage token={user.token} toast={toast}/>}
            {page==="reports"     && <ReportsPage token={user.token}/>}
            {page==="blacklist"   && <BlacklistPage token={user.token} toast={toast}/>}
            {page==="admins"      && <AdminsPage token={user.token} toast={toast}/>}
          </div>
        </div>
      </div>
      <Toasts ts={ts}/>
    </>
  );
}
